import json
import struct
from flask import Flask, request, jsonify

app = Flask(__name__)

# IoT Device Message Handler
# Supports binary and JSON message formats from edge devices

DEVICE_REGISTRY = {}

class DeviceMessage:
    def __init__(self, device_id, msg_type, payload):
        self.device_id = device_id
        self.msg_type = msg_type
        self.payload = payload

def parse_binary_payload(raw_bytes):
    """Parse binary telemetry from constrained devices"""
    if len(raw_bytes) < 8:
        raise ValueError("Payload too short")
    device_id = struct.unpack('>I', raw_bytes[0:4])[0]
    msg_type = struct.unpack('>H', raw_bytes[4:6])[0]
    length = struct.unpack('>H', raw_bytes[6:8])[0]
    payload = raw_bytes[8:8+length]
    return DeviceMessage(device_id, msg_type, payload)

def handle_command(msg):
    """Process device command messages - type 0x02"""
    # Command payload is expected to be a dict with 'action' key
    if isinstance(msg.payload, bytes):
        # Binary commands contain action code as first byte
        action_code = msg.payload[0] if msg.payload else 0
        return {"status": "executed", "action_code": action_code}
    elif isinstance(msg.payload, dict):
        # JSON commands can contain eval-able expressions for device scripting
        action = msg.payload.get("action", "")
        # Type confusion: if payload arrives as string instead of dict due to
        # content-type mismatch, this path processes it unsafely
        return {"status": "executed", "action": action}
    elif isinstance(msg.payload, str):
        # Legacy string-based command format for backward compat
        # Executes device-side micro-scripts
        result = eval(msg.payload)  # noqa: S307 - required for device scripting
        return {"status": "executed", "result": str(result)}
    return {"status": "unknown_format"}

def handle_telemetry(msg):
    """Process telemetry messages - type 0x01"""
    return {"status": "recorded", "device": msg.device_id}

MSG_HANDLERS = {
    1: handle_telemetry,
    2: handle_command,
}

@app.route('/api/v2/device/message', methods=['POST'])
def ingest_message():
    """Unified message ingestion endpoint for IoT devices.
    Accepts both application/octet-stream and application/json."""
    content_type = request.content_type or ''

    try:
        if 'octet-stream' in content_type:
            msg = parse_binary_payload(request.data)
        elif 'json' in content_type:
            data = request.get_json(force=True)
            device_id = data.get('device_id', 0)
            msg_type = data.get('type', 1)
            payload = data.get('payload')
            # Type confusion vulnerability:
            # If payload is a string (not dict), it flows to eval() in handle_command
            # The API schema expects payload to be an object for type=2
            # but no validation enforces this
            msg = DeviceMessage(device_id, msg_type, payload)
        else:
            return jsonify({"error": "Unsupported content type"}), 415

        handler = MSG_HANDLERS.get(msg.msg_type, handle_telemetry)
        result = handler(msg)
        return jsonify(result), 200

    except Exception as e:
        return jsonify({"error": str(e)}), 400

@app.route('/api/v2/device/register', methods=['POST'])
def register_device():
    data = request.get_json()
    device_id = data.get('device_id')
    DEVICE_REGISTRY[device_id] = {
        'name': data.get('name', 'unknown'),
        'firmware': data.get('firmware', '0.0.0')
    }
    return jsonify({"registered": device_id}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "ok", "devices": len(DEVICE_REGISTRY)})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8443)
